from pathlib import Path

from docx import Document
from docx.enum.section import WD_SECTION_START
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Mm, Pt


ROOT = Path(__file__).resolve().parent
OUT = ROOT / "Глава_3_Экспериментальная_часть_исправленная_4.docx"
FIG = ROOT / "_extracted" / "prediploma_figures"
CHARTS = ROOT / "_extracted" / "excel_charts_py"

FONT = "Times New Roman"
BODY_SIZE = 12


def set_run(run, size=BODY_SIZE, bold=False):
    run.font.name = FONT
    run._element.rPr.rFonts.set(qn("w:eastAsia"), FONT)
    run.font.size = Pt(size)
    run.bold = bold


def format_p(p, justify=True, first_line=True):
    pf = p.paragraph_format
    pf.space_before = Pt(0)
    pf.space_after = Pt(0)
    pf.line_spacing = 1.5
    if first_line:
        pf.first_line_indent = Cm(1.25)
    if justify:
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    for r in p.runs:
        set_run(r)


def p(doc, text):
    par = doc.add_paragraph()
    par.add_run(text)
    format_p(par)
    return par


def heading(doc, text, main=False):
    par = doc.add_paragraph()
    run = par.add_run(text)
    set_run(run, bold=True)
    pf = par.paragraph_format
    pf.first_line_indent = None if main else Cm(1.25)
    pf.space_before = Pt(0 if main else 24)
    pf.space_after = Pt(12)
    pf.line_spacing = 1.5
    par.alignment = WD_ALIGN_PARAGRAPH.CENTER if main else WD_ALIGN_PARAGRAPH.LEFT


def table_title(doc, text):
    par = doc.add_paragraph()
    par.add_run(text)
    format_p(par, justify=False, first_line=False)


def borders(table):
    tbl_pr = table._tbl.tblPr
    tbl_borders = tbl_pr.first_child_found_in("w:tblBorders")
    if tbl_borders is None:
        tbl_borders = OxmlElement("w:tblBorders")
        tbl_pr.append(tbl_borders)
    for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
        el = tbl_borders.find(qn("w:" + edge))
        if el is None:
            el = OxmlElement("w:" + edge)
            tbl_borders.append(el)
        el.set(qn("w:val"), "single")
        el.set(qn("w:sz"), "6")
        el.set(qn("w:space"), "0")
        el.set(qn("w:color"), "000000")


def cell(cell, text, bold=False, size=10):
    cell.text = ""
    par = cell.paragraphs[0]
    par.alignment = WD_ALIGN_PARAGRAPH.CENTER
    par.paragraph_format.space_before = Pt(0)
    par.paragraph_format.space_after = Pt(0)
    par.paragraph_format.line_spacing = 1.0
    run = par.add_run(str(text))
    set_run(run, size=size, bold=bold)
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER


def add_table(doc, headers, rows, size=10):
    t = doc.add_table(rows=1, cols=len(headers))
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    t.autofit = True
    for i, h in enumerate(headers):
        cell(t.rows[0].cells[i], h, bold=True, size=size)
    for row in rows:
        cells = t.add_row().cells
        for i, value in enumerate(row):
            cell(cells[i], value, size=size)
    borders(t)
    return t


def figure(doc, path, caption, width=13.5):
    path = Path(path)
    par = doc.add_paragraph()
    par.alignment = WD_ALIGN_PARAGRAPH.CENTER
    par.paragraph_format.space_before = Pt(0)
    par.paragraph_format.space_after = Pt(0)
    par.add_run().add_picture(str(path), width=Cm(width))
    cap = doc.add_paragraph()
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.space_before = Pt(0)
    cap.paragraph_format.space_after = Pt(0)
    cap.paragraph_format.line_spacing = 1.5
    run = cap.add_run(caption)
    set_run(run)


def three_figures(doc, paths, caption):
    t = doc.add_table(rows=1, cols=3)
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, path in enumerate(paths):
        par = t.rows[0].cells[i].paragraphs[0]
        par.alignment = WD_ALIGN_PARAGRAPH.CENTER
        par.add_run().add_picture(str(path), width=Cm(5.0))
    cap = doc.add_paragraph()
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = cap.add_run(caption)
    set_run(run)


def setup():
    doc = Document()
    sec = doc.sections[0]
    sec.start_type = WD_SECTION_START.NEW_PAGE
    sec.page_width = Mm(210)
    sec.page_height = Mm(297)
    sec.left_margin = Mm(30)
    sec.right_margin = Mm(15)
    sec.top_margin = Mm(20)
    sec.bottom_margin = Mm(20)
    style = doc.styles["Normal"]
    style.font.name = FONT
    style._element.rPr.rFonts.set(qn("w:eastAsia"), FONT)
    style.font.size = Pt(BODY_SIZE)
    return doc


